use std::process;

pub fn parse_progress_arg(args: &[String]) -> i32 {
    if args.len() > 1 {
        stoi_or_abort(&args[1])
    } else {
        150
    }
}

fn stoi_or_abort(input: &str) -> i32 {
    match stoi_like(input) {
        Ok(value) => value,
        Err(StoiError::InvalidArgument) => abort_stoi("std::invalid_argument"),
        Err(StoiError::OutOfRange) => abort_stoi("std::out_of_range"),
    }
}

fn abort_stoi(exception_name: &str) -> ! {
    eprintln!(
        "terminate called after throwing an instance of '{}'",
        exception_name
    );
    eprintln!("  what():  stoi");
    process::abort();
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum StoiError {
    InvalidArgument,
    OutOfRange,
}

fn stoi_like(input: &str) -> Result<i32, StoiError> {
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index < bytes.len() && bytes[index].is_ascii_whitespace() {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() {
        match bytes[index] {
            b'+' => index += 1,
            b'-' => {
                negative = true;
                index += 1;
            }
            _ => {}
        }
    }

    let digit_start = index;
    let limit = if negative {
        i32::MAX as i64 + 1
    } else {
        i32::MAX as i64
    };

    let mut value = 0i64;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        let digit = (bytes[index] - b'0') as i64;
        value = value * 10 + digit;
        if value > limit {
            return Err(StoiError::OutOfRange);
        }
        index += 1;
    }

    if index == digit_start {
        return Err(StoiError::InvalidArgument);
    }

    if negative {
        if value == i32::MAX as i64 + 1 {
            Ok(i32::MIN)
        } else {
            Ok(-(value as i32))
        }
    } else {
        Ok(value as i32)
    }
}

#[cfg(test)]
mod tests {
    use super::parse_progress_arg;
    use super::stoi_like;
    use super::StoiError;

    #[test]
    fn uses_default_progress() {
        let args = vec!["bin".to_string()];
        assert_eq!(parse_progress_arg(&args), 150);
    }

    #[test]
    fn accepts_stoi_prefixes() {
        assert_eq!(stoi_like("1abc"), Ok(1));
        assert_eq!(stoi_like("   +12"), Ok(12));
        assert_eq!(stoi_like("-50"), Ok(-50));
    }

    #[test]
    fn rejects_invalid_and_out_of_range_inputs() {
        assert_eq!(stoi_like("abc"), Err(StoiError::InvalidArgument));
        assert_eq!(
            stoi_like("999999999999999999999999"),
            Err(StoiError::OutOfRange)
        );
    }
}

